/** Research export (JSON full fidelity, CSV one row per session) and validation pairs. */
import { HB_ROMAN, MOVEMENT_TASKS, blandAltman, icc, weightedKappa } from '../core';
import { APP_INFO } from './records';
import type { AppState } from './store';
import type { ClinicianRating, SessionRecord } from './types';

export function download(filename: string, content: string, type: string): void {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const a = Object.assign(document.createElement('a'), { href: url, download: filename });
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function exportJson(s: AppState): string {
  const p = s.profile;
  return JSON.stringify(
    {
      format: 'fpc-export/1',
      exportedAt: new Date().toISOString(),
      app: APP_INFO,
      // Direct identifiers are never exported.
      subject: p ? { affectedSide: p.affectedSide, onsetDate: p.onsetDate, etiology: p.etiology, birthYear: p.birthYear } : null,
      sessions: s.sessions.map((x) => ({ ...x, integrityVerified: s.integrity[x.id] ?? false })),
      clinicianRatings: s.ratings,
      rehabLogs: s.rehab,
      synkinesisFinder: s.synk.map((x) => ({ ...x, integrityVerified: s.integrity[x.id] ?? false })),
    },
    null,
    1,
  );
}

const csvCell = (v: unknown): string => {
  if (v === null || v === undefined || (typeof v === 'number' && !Number.isFinite(v))) return '';
  const t = typeof v === 'number' ? String(Math.round(v * 10000) / 10000) : String(v);
  return /[",\n]/.test(t) ? `"${t.replace(/"/g, '""')}"` : t;
};

export function latestRating(ratings: readonly ClinicianRating[], sessionId: string): ClinicianRating | undefined {
  return ratings.filter((r) => r.sessionId === sessionId).sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
}

export function exportCsv(s: AppState): string {
  const head = [
    'session_id',
    'created_at',
    'days_since_onset',
    'mode',
    'status',
    'affected_side',
    'suggested_side',
    'algorithm_version',
    'scoring_version',
    'composite_est',
    'rest_score',
    'voluntary_score',
    'synkinesis_score',
    'hb_est',
    'hb_rule',
    'function_index',
    'forehead_pct',
    'eye_pct',
    'midface_pct',
    'mouth_pct',
    'eye_closure_complete',
    ...MOVEMENT_TASKS.flatMap((t) => [`${t}_ratio`, `${t}_grade`, `${t}_synk`, `${t}_reliable`]),
    'rest_eye_item',
    'rest_cheek_item',
    'rest_mouth_item',
    'mm_per_unit',
    'warnings',
    'model_sha256',
    'delegate',
    'integrity_hash',
    'integrity_verified',
    'clin_rater',
    'clin_hb',
    'clin_sb_composite',
  ];
  const rows = s.sessions.map((x) => {
    const a = x.analysis;
    const sc = a.scores;
    const rt = latestRating(s.ratings, x.id);
    return [
      x.id,
      x.createdAt,
      x.daysSinceOnset,
      x.mode,
      a.status,
      a.affectedSide,
      a.suggestedAffectedSide,
      a.algorithm.version,
      a.algorithm.scoringVersion,
      sc?.composite,
      sc?.restScore,
      sc?.voluntaryScore,
      sc?.synkinesisScore,
      sc ? HB_ROMAN[sc.houseBrackmann.grade] : '',
      sc?.houseBrackmann.ruleId,
      sc?.functionIndex,
      sc?.regional.forehead,
      sc?.regional.eye,
      sc?.regional.midface,
      sc?.regional.mouth,
      sc?.eyeClosureComplete,
      ...MOVEMENT_TASKS.flatMap((t) => {
        const m = a.tasks[t];
        return [m?.ratio, m?.grade, m?.synkinesisGrade, m?.reliable];
      }),
      a.rest?.items.eye,
      a.rest?.items.cheek,
      a.rest?.items.mouth,
      a.mmPerUnit,
      a.warnings.map((w) => (w.task ? `${w.code}:${w.task}` : w.code)).join(' '),
      x.engine?.modelSha256,
      x.engine?.delegate,
      x.integrity.hash,
      s.integrity[x.id],
      rt?.raterId,
      rt?.houseBrackmann,
      rt?.sunnybrookComposite,
    ].map(csvCell);
  });
  return '﻿' + [head.join(','), ...rows.map((r) => r.join(','))].join('\n');
}

export interface Agreement {
  nComposite: number;
  iccComposite: number | null;
  ba: ReturnType<typeof blandAltman> | null;
  nHb: number;
  kappaHb: number | null;
  exactHb: number | null;
  withinOneHb: number | null;
}

/** App estimate vs latest clinician rating per session (complete sessions only). */
export function agreement(sessions: readonly SessionRecord[], ratings: readonly ClinicianRating[]): Agreement {
  const comp: [number, number][] = [];
  const hb: [number, number][] = [];
  for (const s of sessions) {
    const sc = s.analysis.scores;
    const r = latestRating(ratings, s.id);
    if (!sc || !r) continue;
    if (r.sunnybrookComposite !== null) comp.push([sc.composite, r.sunnybrookComposite]);
    if (r.houseBrackmann !== null) hb.push([sc.houseBrackmann.grade, r.houseBrackmann]);
  }
  const ok = comp.length >= 3;
  const okHb = hb.length >= 3;
  return {
    nComposite: comp.length,
    iccComposite: ok ? icc(comp, 'A,1') : null,
    ba: ok
      ? blandAltman(
          comp.map((p) => p[0]),
          comp.map((p) => p[1]),
        )
      : null,
    nHb: hb.length,
    kappaHb: okHb
      ? weightedKappa(
          hb.map((p) => p[0] - 1),
          hb.map((p) => p[1] - 1),
          6,
          'quadratic',
        )
      : null,
    exactHb: okHb ? hb.filter((p) => p[0] === p[1]).length / hb.length : null,
    withinOneHb: okHb ? hb.filter((p) => Math.abs(p[0] - p[1]) <= 1).length / hb.length : null,
  };
}
