import { useEffect, useState } from 'preact/hooks';
import { ALGORITHM_ID, ALGORITHM_VERSION, SCORING_VERSION } from '../../core';
import { FEATURES, PROFILE } from '../../config';
import { CONSENT_VERSION, INTENDED_USE } from '../../data/consent';
import { download, exportCsv, exportJson } from '../../data/export';
import { APP_INFO } from '../../data/records';
import { countSnapshots, deleteAllSnapshots } from '../../data/snapshots';
import { actions, getState, useApp } from '../../data/store';
import { DOSE_VERSION } from '../../rehab/dose';
import { PLANNER_VERSION } from '../../rehab/planner';
import MODEL_LOCK from '../../vision/model-lock.json';
import { AppBar, Notice, Segmented } from '../components/common';
import { ImportBackup } from '../components/ImportBackup';
import { getTheme, setTheme, type ThemePref } from '../theme';
import { Icon } from '../icons';
import { ProfileFields, type ProfileDraft } from './Onboarding';

declare const __MP_VERSION__: string;

export function Settings() {
  const [photoCount, setPhotoCount] = useState(0);
  useEffect(() => {
    countSnapshots().then(setPhotoCount, () => setPhotoCount(0));
  }, []);
  const { profile, sessions } = useApp();
  const [draft, setDraft] = useState<ProfileDraft | null>(null);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [busy, setBusy] = useState(false);
  const [theme, setThemeState] = useState<ThemePref>(getTheme);
  if (!profile) return null;
  const stamp = new Date().toISOString().slice(0, 10);

  return (
    <>
      <AppBar title="설정" />
      <main class="main">
        <div class="section-title">내 정보</div>
        <div class="card">
          {draft ? (
            <>
              <ProfileFields value={draft} onChange={setDraft} />
              {draft.affectedSide !== profile.affectedSide && (
                <Notice tone="warn">
                  <span class="small">마비된 쪽을 바꾸면 이후 평가부터 적용됩니다. 이전 기록은 기록 당시 설정을 유지합니다.</span>
                </Notice>
              )}
              <div class="row">
                <button class="btn grow" onClick={() => setDraft(null)}>
                  취소
                </button>
                <button
                  class="btn primary grow"
                  onClick={async () => {
                    await actions.saveProfile({ ...profile, ...draft });
                    setDraft(null);
                  }}
                >
                  저장
                </button>
              </div>
            </>
          ) : (
            <button
              class="list-item"
              onClick={() =>
                setDraft({
                  affectedSide: profile.affectedSide,
                  onsetDate: profile.onsetDate,
                  etiology: profile.etiology,
                  nickname: profile.nickname,
                  birthYear: profile.birthYear,
                })
              }
            >
              <div class="grow">
                <div>{profile.nickname || '이름 없음'}</div>
                <div class="small ink2">
                  마비 쪽 {profile.affectedSide === 'left' ? '왼쪽' : '오른쪽'} · 발병일 {profile.onsetDate}
                </div>
              </div>
              <Icon name="chev" class="chev" />
            </button>
          )}
        </div>

        <div class="section-title">사용 환경</div>
        <div class="card">
          <label class="check" style={{ padding: 0 }}>
            <input
              type="checkbox"
              checked={profile.voiceGuide}
              onChange={(e) => actions.saveProfile({ ...profile, voiceGuide: (e.target as HTMLInputElement).checked })}
            />
            <span>
              음성 안내 <span class="small muted">— 평가·운동 중 지시를 읽어 줍니다</span>
            </span>
          </label>
          <div class="field">
            <span>얼굴 그림 방향</span>
            <Segmented
              label="얼굴 그림 방향"
              value={profile.viewMode}
              onChange={(v) => actions.saveProfile({ ...profile, viewMode: v })}
              options={[
                { value: 'mirror', label: '거울처럼' },
                { value: 'clinical', label: '마주 본 모습(임상)' },
              ]}
            />
          </div>
          <div class="field">
            <span>화면 테마</span>
            <Segmented
              label="화면 테마"
              value={theme}
              onChange={(v) => {
                setTheme(v);
                setThemeState(v);
              }}
              options={[
                { value: 'light', label: '밝게' },
                { value: 'dark', label: '어둡게' },
                { value: 'system', label: '기기 설정' },
              ]}
            />
          </div>
        </div>

        <div class="section-title">평가 사진</div>
        <div class="card">
          <label class="check" style={{ padding: 0 }}>
            <input
              type="checkbox"
              checked={!!profile.savePhotos}
              onChange={async (e) => {
                const on = (e.target as HTMLInputElement).checked;
                if (on && !confirm(PHOTO_CONSENT)) {
                  (e.target as HTMLInputElement).checked = false;
                  return;
                }
                if (
                  !on &&
                  photoCount > 0 &&
                  confirm(`저장된 사진(${photoCount}회 평가분)도 지울까요? 취소하면 사진은 남고 새로 찍지 않습니다.`)
                ) {
                  await deleteAllSnapshots();
                  setPhotoCount(0);
                }
                await actions.saveProfile({ ...profile, savePhotos: on });
              }}
            />
            <span>
              평가 사진 저장 <span class="small muted">— 동작마다 표정을 유지한 순간 1장씩, 이 폰에만</span>
            </span>
          </label>
          <p class="xsmall muted" style={{ margin: '6px 0 0' }}>
            결과의 ‘얼굴 움직임 모양’에서 선 그림 대신 사진으로 볼 수 있습니다. 사진은 서버로 보내지 않고, 데이터 내보내기에도 들어가지
            않습니다.
          </p>
          {photoCount > 0 && (
            <button
              class="btn sm block"
              style={{ marginTop: '8px' }}
              onClick={async () => {
                if (!confirm(`저장된 사진(${photoCount}회 평가분)을 모두 지웁니다. 측정 기록은 남습니다.`)) return;
                await deleteAllSnapshots();
                setPhotoCount(0);
              }}
            >
              저장된 사진 모두 지우기 ({photoCount}회 평가분)
            </button>
          )}
        </div>

        <div class="section-title">데이터</div>
        <div class="card tight">
          <div class="list">
            <button class="list-item" onClick={() => download(`facial-palsy-${stamp}.json`, exportJson(getState()), 'application/json')}>
              <Icon name="download" />
              <div class="grow">
                전체 기록 내보내기 (JSON)
                <div class="xsmall muted">무결성 해시·버전 정보 포함, 이름 제외</div>
              </div>
            </button>
            <button
              class="list-item"
              onClick={() => download(`facial-palsy-${stamp}.csv`, exportCsv(getState()), 'text/csv;charset=utf-8')}
            >
              <Icon name="download" />
              <div class="grow">
                평가 요약 내보내기 (CSV)
                <div class="xsmall muted">평가 1회당 1행, 임상가 평가 포함</div>
              </div>
            </button>
            <ImportBackup />
            {FEATURES.researchTools && (
              <a class="list-item" href="#/research">
                <Icon name="flask" />
                <div class="grow">
                  연구 도구
                  <div class="xsmall muted">임상가 평가 입력, 일치도(ICC·κ), 사진 세트 분석</div>
                </div>
                <Icon name="chev" class="chev" />
              </a>
            )}
            {FEATURES.demo && (
              <a class="list-item" href="#/cases">
                <Icon name="image" />
                <div class="grow">
                  실제 사진 사례
                  <div class="xsmall muted">공개 라이선스 안면마비 사진 분석·경과 보기</div>
                </div>
                <Icon name="chev" class="chev" />
              </a>
            )}
            {FEATURES.demo && (
              <button
                class="list-item"
                disabled={busy}
                onClick={async () => {
                  if (!confirm('현재 기록을 모두 지우고 데모 데이터로 바꿉니다. 계속할까요?')) return;
                  setBusy(true);
                  await actions.loadDemo();
                  setBusy(false);
                }}
              >
                <Icon name="chart" />
                <div class="grow">
                  데모 데이터로 교체
                  <div class="xsmall muted">합성 데이터 10회 평가 · 기존 기록 삭제</div>
                </div>
              </button>
            )}
          </div>
        </div>
        <div class="card tight">
          {!confirmDelete ? (
            <button class="btn danger block" onClick={() => setConfirmDelete(true)}>
              <Icon name="trash" /> 모든 데이터 삭제
            </button>
          ) : (
            <>
              <Notice tone="danger">
                <span class="small">
                  평가 {sessions.length}건과 운동 기록, 프로필이 이 기기에서 영구히 삭제됩니다. 필요하면 먼저 내보내기 하세요.
                </span>
              </Notice>
              <div class="row">
                <button class="btn grow" onClick={() => setConfirmDelete(false)}>
                  취소
                </button>
                <button
                  class="btn grow"
                  style={{ background: 'var(--critical)', color: '#fff' }}
                  onClick={async () => {
                    await actions.deleteAll();
                    location.hash = '/';
                  }}
                >
                  영구 삭제
                </button>
              </div>
            </>
          )}
        </div>

        <div class="section-title">정보</div>
        <details class="card tight">
          <summary class="ink2" style={{ fontWeight: 600 }}>
            사용 목적과 소프트웨어 구성
          </summary>
          <p class="small">{INTENDED_USE}</p>
          <table class="data">
            <tbody>
              <tr>
                <td>앱</td>
                <td>
                  v{APP_INFO.version} ({PROFILE})
                </td>
              </tr>
              <tr>
                <td>빌드</td>
                <td class="xsmall">{APP_INFO.build}</td>
              </tr>
              <tr>
                <td>측정 알고리즘</td>
                <td>
                  {ALGORITHM_ID} v{ALGORITHM_VERSION}
                </td>
              </tr>
              <tr>
                <td>점수 매핑</td>
                <td>{SCORING_VERSION}</td>
              </tr>
              <tr>
                <td>재활 계획 규칙</td>
                <td>{PLANNER_VERSION}</td>
              </tr>
              <tr>
                <td>운동 양 조절</td>
                <td>{DOSE_VERSION}</td>
              </tr>
              <tr>
                <td>동의 문서</td>
                <td>{CONSENT_VERSION}</td>
              </tr>
              <tr>
                <td>얼굴 인식 (SOUP)</td>
                <td class="xsmall">MediaPipe Tasks Vision {__MP_VERSION__}</td>
              </tr>
              <tr>
                <td>모델</td>
                <td class="xsmall">{MODEL_LOCK.name}</td>
              </tr>
              <tr>
                <td>모델 SHA-256</td>
                <td class="mono">{MODEL_LOCK.sha256}</td>
              </tr>
            </tbody>
          </table>
          <p class="xsmall muted">연구용 프로토타입입니다. 의료기기로 허가받지 않았습니다.</p>
        </details>
      </main>
    </>
  );
}

const PHOTO_CONSENT = [
  '평가 사진 저장을 켭니다.',
  '',
  '· 평가할 때 동작마다 얼굴 사진 1장씩(안정 포함 6장)이 이 폰 안에만 저장됩니다.',
  '· 서버로 보내지 않고, 데이터 내보내기에도 들어가지 않습니다.',
  '· 얼굴 사진은 민감한 개인정보이니 폰 잠금을 켜 두세요.',
  '· 언제든 이 화면에서 끄거나 지울 수 있고, 모든 데이터 삭제 때 함께 지워집니다.',
  '',
  '계속할까요?',
].join('\n');
