/**
 * Rule-based personalisation of the daily rehabilitation plan.
 * Pure and deterministic: (profile facts, latest assessment) → plan with a
 * human-readable reason for every item (explainability requirement SRS-RHB-002).
 */
import type { AnalysisResult } from '../core';
import { EXERCISES, REGION_LABEL, type Exercise, type Phase, type Region } from './exercises';
import { regionFinding, type FaceRegion } from './findings';

export const PLANNER_VERSION = 'RP-0.1.0';

export interface PlanInput {
  daysSinceOnset: number;
  /** Most recent complete assessment, if any. */
  latest: AnalysisResult | null;
}

export interface PlanItem {
  exercise: Exercise;
  reason: string;
  /** Region whose measured weakness put this item on the plan. */
  region?: FaceRegion;
}

export interface Plan {
  version: string;
  phase: Phase;
  phaseReason: string;
  sessionsPerDay: number;
  items: PlanItem[];
  notices: string[];
}

/** Days after onset at which the plan switches from acute to recovery. */
export const ACUTE_DAYS = 21;
/** Total synkinesis score at or above which the synkinesis programme is used. */
export const SYNKINESIS_THRESHOLD = 3;

type Deficits = Record<'forehead' | 'eye' | 'midface' | 'mouth', number>;

function phaseOf(input: PlanInput): { phase: Phase; reason: string } {
  const synk = input.latest?.scores?.synkinesisScore ?? 0;
  if (synk >= SYNKINESIS_THRESHOLD) {
    return { phase: 'synkinesis', reason: `최근 평가에서 동반운동 점수가 ${synk}점으로 확인되어 동반운동 관리 단계를 적용합니다.` };
  }
  if (input.daysSinceOnset < ACUTE_DAYS) {
    return {
      phase: 'acute',
      reason: `발병 ${input.daysSinceOnset + 1}일째로 급성기(3주 이내)입니다. 부드러운 마사지와 눈 보호 위주로 진행합니다.`,
    };
  }
  return { phase: 'recovery', reason: `발병 ${input.daysSinceOnset + 1}일째 회복기입니다. 거울을 보며 작고 대칭적인 움직임을 연습합니다.` };
}

export function buildPlan(input: PlanInput): Plan {
  const { phase, reason: phaseReason } = phaseOf(input);
  const s = input.latest?.scores ?? null;
  const items: PlanItem[] = [];
  const notices: string[] = [];
  const add = (id: string, reason: string, region?: FaceRegion) => {
    const ex = EXERCISES.find((e) => e.id === id);
    if (ex && ex.phases.includes(phase) && !items.some((i) => i.exercise.id === id)) items.push({ exercise: ex, reason, region });
  };

  const eyeIncomplete = s ? !s.eyeClosureComplete : phase === 'acute';
  add('relax-breath', '운동 전 긴장을 풀어 불필요한 동반 수축을 줄입니다.');
  if (eyeIncomplete) {
    add('eyecare', s ? '최근 평가에서 눈이 완전히 감기지 않아 눈 보호가 필요합니다.' : '급성기에는 눈 보호가 가장 중요합니다.');
    notices.push('눈이 완전히 감기지 않습니다. 인공눈물·안연고 사용과 수면 중 눈 보호에 대해 주치의와 상의하세요.');
  }

  // Region deficits (100 − % of healthy side); without an assessment all regions are treated alike.
  const deficits: Deficits = s
    ? {
        forehead: 100 - s.regional.forehead,
        eye: 100 - s.regional.eye,
        midface: 100 - s.regional.midface,
        mouth: 100 - s.regional.mouth,
      }
    : { forehead: 50, eye: 50, midface: 50, mouth: 50 };
  const ranked = (Object.entries(deficits) as [keyof Deficits, number][]).sort((a, b) => b[1] - a[1]);
  const pctText = (r: keyof Deficits) =>
    s ? `${REGION_LABEL[r as Region]}: ${regionFinding(input.latest!, r)!.evidence}` : `${REGION_LABEL[r as Region]} 기본 관리`;

  const massageFor: Record<keyof Deficits, string> = {
    forehead: 'massage-forehead',
    eye: 'massage-eye',
    midface: 'massage-cheek',
    mouth: 'massage-lips',
  };
  /** Selective stretches of the reference video per region (most specific first). */
  const stretchFor: Record<keyof Deficits, string[]> = {
    forehead: ['frontalis-lift', 'brow-relax'],
    eye: ['eye-open', 'orbicularis-sweep'],
    midface: ['levator-labii', 'levator-superioris'],
    mouth: ['zygomatic-lift', 'corner-lift'],
  };
  const nmrFor: Record<keyof Deficits, string[]> = {
    forehead: ['nmr-brow'],
    eye: ['nmr-eye'],
    midface: ['nmr-snarl'],
    mouth: ['nmr-smile', 'nmr-pucker'],
  };

  if (phase === 'acute') {
    for (const [r] of ranked) add(massageFor[r], `${pctText(r)} — 급성기에는 부드러운 마사지로 관리합니다.`, s ? r : undefined);
    add('nmr-eye', '눈 감기는 급성기에도 가볍게 시도할 수 있는 동작입니다.');
    notices.push('급성기에는 최대 힘으로 얼굴을 움직이는 운동과 전기자극을 피하세요. 치료 방법은 주치의와 상의하세요.');
  } else if (phase === 'recovery') {
    const needs = ranked.filter(([, d]) => d >= 10);
    for (const [r, d] of needs.slice(0, 3)) {
      for (const id of nmrFor[r]) add(id, `${pctText(r)} — ${d >= 50 ? '가장 약해' : '약해'} 우선 배정했습니다.`, r);
    }
    for (const [r] of needs.slice(0, 2)) add(massageFor[r], `${pctText(r)} — 운동 전 준비 마사지입니다.`, r);
    if (deficits.mouth >= 20) add('nmr-cheek-puff', '입 움직임이 약해 입술 닫는 힘을 함께 연습합니다.');
    // Selective stretching is recommended from the early phase onward (reference video).
    if (needs[0]) add(stretchFor[needs[0][0]][0]!, `${pctText(needs[0][0])} — 가장 약한 부위의 선택적 스트레칭입니다.`, needs[0][0]);
    if (needs.length === 0) add('nmr-smile', '모든 부위가 90% 이상 회복되어 유지 운동만 권장합니다.');
  } else {
    const synkEye = s ? ['smile', 'snarl', 'pucker'].some((t) => (input.latest!.tasks[t as 'smile']?.synkinesisGrade ?? 0) > 0) : true;
    const synkMouth = s ? ['brow', 'eyeClose'].some((t) => (input.latest!.tasks[t as 'brow']?.synkinesisGrade ?? 0) > 0) : true;
    add('massage-eye', '동반운동으로 긴장된 눈 주위 근육을 먼저 풀어 줍니다.');
    if (synkEye) {
      add('eye-open', '눈이 함께 작아지는 동반운동이 있어 짧아진 눈둘레근을 안쪽→바깥쪽으로 늘입니다.', 'eye');
      add('orbicularis-sweep', '이어서 눈둘레근을 위·아래로 늘입니다.', 'eye');
    }
    add('zygomatic-lift', '광대근을 늘여 입꼬리가 과하게 당기는 긴장을 풀어 줍니다.', synkMouth ? 'mouth' : undefined);
    add('corner-lift', '입꼬리올림근을 늘여 웃을 때 과하게 당기는 긴장을 풀어 줍니다.', synkMouth ? 'mouth' : undefined);
    if (synkEye) add('dissoc-smile-eye', '입을 움직일 때 눈이 함께 작아지는 동반운동이 측정되었습니다.', 'eye');
    if (synkMouth) add('dissoc-eye-mouth', '눈을 감을 때 입꼬리가 따라 움직이는 동반운동이 측정되었습니다.', 'mouth');
    add('platysma-lift', '입 움직임과 함께 목이 당기는 긴장을 완화합니다.');
    add('massage-cheek', '처진 볼과 입꼬리 주위를 부드럽게 풀어 줍니다.');
    notices.push('동반운동이 있을 때는 근력 강화보다 이완·스트레칭·분리 운동이 우선입니다. 보툴리눔 주사 등 치료는 주치의와 상의하세요.');
  }

  if (input.daysSinceOnset >= 21 && s && s.functionIndex < 30) {
    notices.push('발병 3주 이후에도 움직임이 매우 적습니다. 아직 진료를 받지 않았다면 이비인후과·신경과·재활의학과 진료를 권합니다.');
  }

  return { version: PLANNER_VERSION, phase, phaseReason, sessionsPerDay: phase === 'acute' ? 2 : 3, items, notices };
}

export const PHASE_LABEL: Record<Phase, string> = {
  acute: '급성기',
  recovery: '회복기',
  synkinesis: '동반운동 관리기',
};
