/**
 * FPA-MUSC: per-muscle movement (eFACE-style detail) from the assessment capture.
 *
 * Each item is one muscle action measured on both sides against the rest reference (same gate,
 * alignment and face frame as FPA-GEOM), at the frames where that action peaks (both sides summed).
 * ratio = affected / healthy. Informative detail only: the scores stay with FPA-GEOM.
 */
import { AGGREGATION, alignTo, gate, medianShape, selectPeakFrames } from './analyze';
import { faceFrame, toFaceCoords, toPixels } from './geometry';
import { SIDE, otherSide, outwardSign } from './landmarks';
import { browLevel, eyeAperture, irisDiameter, mouthCorner } from './measures';
import { DEFAULT_QUALITY, type QualityThresholds } from './quality';
import { mean, median } from './stats';
import type { FrameObservation, Side, SidePair, Vec2 } from './types';

export const MUSCLE_ID = 'FPA-MUSC';
export const MUSCLE_VERSION = '0.1.1';

/** Expressions the muscle items are read from. */
export type MuscleExpression = 'brow' | 'eyeGentle' | 'eyeTight' | 'smile' | 'snarl' | 'lowerLip' | 'pucker';

export type MuscleId = 'frontalis' | 'orbOculiGentle' | 'orbOculiTight' | 'zygMajor' | 'upperLipLift' | 'alaLift' | 'lipDepressors' | 'orbOris';

/** Lower-lip vermilion points lateral of the midline (depressor labii inferioris / anguli oris). */
const LOWER_LIP: Record<Side, readonly number[]> = { right: [146, 91, 181], left: [375, 321, 405] };

type Face = readonly Vec2[];

interface ItemDef {
  expression: MuscleExpression;
  /** Movement of one side against rest (≥ 0); eye items are closure fractions, others face units. */
  move: (rest: Face, expr: Face, side: Side) => number;
  /** Closure fractions have no mm equivalent. */
  fraction?: boolean;
  /** Shown for reference only (the measure is known to be weak). */
  reference?: boolean;
}

const up = (rest: Face, expr: Face, idx: readonly number[]) => mean(idx.map((i) => rest[i]!.y - expr[i]!.y));
const closure = (rest: Face, expr: Face, side: Side) => Math.min(1, Math.max(0, 1 - eyeAperture(expr, side) / eyeAperture(rest, side)));

export const MUSCLE_ITEMS: Record<MuscleId, ItemDef> = {
  frontalis: { expression: 'brow', move: (r, e, s) => Math.max(0, browLevel(r, s) - browLevel(e, s)) },
  orbOculiGentle: { expression: 'eyeGentle', move: closure, fraction: true },
  orbOculiTight: { expression: 'eyeTight', move: closure, fraction: true },
  zygMajor: {
    expression: 'smile',
    move: (r, e, s) => {
      const a = mouthCorner(r, s);
      const b = mouthCorner(e, s);
      return Math.hypot(Math.max(0, (b.x - a.x) * outwardSign(s)), Math.max(0, a.y - b.y));
    },
  },
  upperLipLift: { expression: 'smile', move: (r, e, s) => Math.max(0, up(r, e, SIDE[s].upperLip)) },
  alaLift: { expression: 'snarl', move: (r, e, s) => Math.max(0, up(r, e, SIDE[s].ala)), reference: true },
  lipDepressors: {
    expression: 'lowerLip',
    move: (r, e, s) => Math.max(0, -up(r, e, [...LOWER_LIP[s], SIDE[s].mouthCorner])),
  },
  orbOris: {
    expression: 'pucker',
    // Corner moving towards the midline (the lip centre moves little in a pucker).
    move: (r, e, s) => Math.max(0, (mouthCorner(r, s).x - mouthCorner(e, s).x) * outwardSign(s)),
    reference: true,
  },
};

export const MUSCLE_ORDER: readonly MuscleId[] = [
  'frontalis',
  'orbOculiGentle',
  'orbOculiTight',
  'zygMajor',
  'upperLipLift',
  'alaLift',
  'lipDepressors',
  'orbOris',
];

export interface MuscleItem {
  /** Movement per side (closure fraction or face units). */
  movement: SidePair;
  /** Affected / healthy, capped at 1.5; null when the healthy side barely moved. */
  ratio: number | null;
  mm: SidePair | null;
  framesUsed: number;
}

export interface MuscleResult {
  algorithm: { id: string; version: string };
  affectedSide: Side;
  items: Partial<Record<MuscleId, MuscleItem>>;
  missing: MuscleId[];
}

export interface MuscleInput {
  affectedSide: Side;
  rest: readonly FrameObservation[];
  expressions: Partial<Record<MuscleExpression, readonly FrameObservation[]>>;
  quality?: QualityThresholds;
}

/** Healthy-side movement below which a ratio is not meaningful (face units; eye: fraction). */
const MIN_HEALTHY = { unit: 0.01, fraction: 0.1 };

export function analyzeMuscles(input: MuscleInput): MuscleResult {
  const aff = input.affectedSide;
  const hea = otherSide(aff);
  const th = input.quality ?? DEFAULT_QUALITY;
  const result: MuscleResult = { algorithm: { id: MUSCLE_ID, version: MUSCLE_VERSION }, affectedSide: aff, items: {}, missing: [] };
  const min = AGGREGATION.minValidFrames.video;
  const restGate = gate(input.rest, th);
  if (restGate.valid.length < min) {
    result.missing = [...MUSCLE_ORDER];
    return result;
  }
  const restList = restGate.valid.map((v) => toPixels(v.obs));
  const restPx = medianShape(restList.map((px) => alignTo(px, restList[0]!).pts));
  const frame = faceFrame(restPx);
  const restF = toFaceCoords(frame, restPx);
  let mmPerUnit: number | null = null;
  if (restF.length >= 478) {
    const irisD = (irisDiameter(restF, 'left') + irisDiameter(restF, 'right')) / 2;
    if (irisD >= 0.12 && irisD <= 0.3) mmPerUnit = AGGREGATION.irisDiameterMm / irisD;
  }
  const faces: Partial<Record<MuscleExpression, Face[]>> = {};
  const facesOf = (e: MuscleExpression): Face[] => {
    if (!faces[e]) {
      const g = gate(input.expressions[e] ?? [], th);
      faces[e] = g.valid.length < min ? [] : g.valid.map(({ obs }) => toFaceCoords(frame, alignTo(toPixels(obs), restPx).pts));
    }
    return faces[e]!;
  };

  for (const id of MUSCLE_ORDER) {
    const def = MUSCLE_ITEMS[id];
    const fs = facesOf(def.expression);
    if (!fs.length) {
      result.missing.push(id);
      continue;
    }
    const per = fs.map((F) => ({ a: def.move(restF, F, aff), h: def.move(restF, F, hea) }));
    const idx = selectPeakFrames(per.map((p) => p.a + p.h));
    const a = median(idx.map((i) => per[i]!.a));
    const h = median(idx.map((i) => per[i]!.h));
    const movement = { [aff]: a, [hea]: h } as unknown as SidePair;
    const floor = def.fraction ? MIN_HEALTHY.fraction : MIN_HEALTHY.unit;
    result.items[id] = {
      movement,
      ratio: h >= floor ? Math.min(1.5, a / h) : null,
      mm: !def.fraction && mmPerUnit ? { right: movement.right * mmPerUnit, left: movement.left * mmPerUnit } : null,
      framesUsed: idx.length,
    };
  }
  return result;
}

/** Whether an item is shown for reference only. */
export const isReferenceMuscle = (id: MuscleId): boolean => !!MUSCLE_ITEMS[id].reference;
