/**
 * Real-patient photo cases bundled with the app (public/cases/).
 * Every photo is openly licensed on Wikimedia Commons; attribution is shown
 * next to each photo in the UI and in CREDITS.md. The app's numbers are
 * computed from these photos by FPA-STILL and are NOT clinical records of
 * the people shown.
 */
import type { Side, StillExpression, StillRegion } from '../core';

export interface CaseSource {
  title: string;
  page: string;
  author: string;
  license: 'CC BY-SA 4.0';
  licenseUrl: string;
  /** How the bundled file differs from the source (CC BY-SA requires indicating changes). */
  changes: string;
}

export interface CasePhoto {
  id: string;
  file: string;
  /** Day number as labelled by the author (onset day = day 1); null if unknown. */
  day: number | null;
  takenAt: string | null;
  expression: StillExpression;
  label: string;
  note?: string;
  exclude?: StillRegion[];
  source: CaseSource;
}

export interface PatientCase {
  id: string;
  title: string;
  subtitle: string;
  description: string;
  etiology: 'bell';
  affectedSide: Side;
  sideNote: string;
  photos: CasePhoto[];
}

const BY_SA = { license: 'CC BY-SA 4.0' as const, licenseUrl: 'https://creativecommons.org/licenses/by-sa/4.0/' };
const commons = (file: string) => `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(file.replace(/ /g, '_'))}`;
const kamphuis = (file: string): CaseSource => ({
  title: file,
  page: commons(file),
  author: 'Andrea Kamphuis',
  ...BY_SA,
  changes: '원본 그대로 (측정선·윤곽은 앱이 화면에 덧그림)',
});
const benjamin = (file: string): CaseSource => ({
  title: file,
  page: commons(file),
  author: 'Benjaminginterr',
  ...BY_SA,
  changes: 'Wikimedia Commons 1280px 축소본 사용 (측정선·윤곽은 앱이 화면에 덧그림)',
});

