/**
 * Photo-based views: measurement overlay on a real photo, face-aligned
 * before/after comparison, region results, timeline and trend chart.
 * Photos are shown unmirrored (as a clinician sees the patient).
 */
import { useState } from 'preact/hooks';
import { CONTOURS, SIDE, STILL_REGIONS, faceFrame, type Side, type StillAnalysis, type StillRegion, type Vec2 } from '../../core';
import { EXPRESSION_LABEL, caseById, type CaseSource } from '../../cases/library';
import { TREND_TASK_LABEL, trendLines, trendSummary as baseSummary } from '../../cases/trend';
import type { PhotoRecord } from '../../data/types';
import { LineChart, Legend, type Series } from './LineChart';

export const REGION_NAME: Record<StillRegion, string> = { brow: '눈썹', eye: '눈', mouth: '입꼬리', midface: '코·볼' };
export const BAND_LABEL = ['대칭', '경미한 차이', '뚜렷한 차이', '큰 차이'] as const;
const BAND_CHIP = ['good', 'accent', 'warn', 'bad'] as const;

/** Plain-language reading of a signed difference (+ = affected side worse). */
export function regionReading(r: StillRegion, mm: number): string {
  const a = Math.abs(mm).toFixed(1);
  if (Math.abs(mm) < 0.5) return '좌우 거의 같음';
  const worse = mm > 0;
  switch (r) {
    case 'brow':
      return worse ? `마비 쪽 눈썹이 ${a}mm 낮음` : `마비 쪽 눈썹이 ${a}mm 높음`;
    case 'eye':
      return worse ? `마비 쪽 눈이 ${a}mm 더 열림` : `마비 쪽 눈이 ${a}mm 더 좁음`;
    case 'mouth':
      return worse ? `마비 쪽 입꼬리가 ${a}mm 낮음` : `마비 쪽 입꼬리가 ${a}mm 높음`;
    case 'midface':
      return worse ? `마비 쪽 콧방울이 ${a}mm 낮음` : `마비 쪽 콧방울이 ${a}mm 높음`;
  }
}

const pts = (a: StillAnalysis): Vec2[] => {
  const p = a.keyframe.points;
  const out: Vec2[] = [];
  for (let i = 0; i + 1 < p.length; i += 2) out.push({ x: p[i]!, y: p[i + 1]! });
  return out;
};

function faceBox(P: readonly Vec2[], margin = 0.28) {
  const oval = CONTOURS.faceOval!.map((i) => P[i]!);
  const xs = oval.map((p) => p.x);
  const ys = oval.map((p) => p.y);
  const [x0, x1, y0, y1] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  const w = x1 - x0;
  const h = y1 - y0;
  return { x: x0 - w * margin, y: y0 - h * margin * 0.8, w: w * (1 + 2 * margin), h: h * (1 + 1.6 * margin) };
}

const COLOR: Record<'aff' | 'healthy', string> = { aff: 'var(--series-2)', healthy: 'var(--series-1)' };

/** Real photo cropped to the face with pupil line, midline and side-by-side level markers. */
export function PhotoMeasure({ record, contours = false }: { record: PhotoRecord; contours?: boolean }) {
  const a = record.analysis;
  if (!a || !record.imageUrl) {
    return (
      <div class="photo-frame">
        {record.imageUrl && <img src={record.imageUrl} alt={record.label} style={{ width: '100%', display: 'block' }} />}
      </div>
    );
  }
  const P = pts(a);
  const box = faceBox(P);
  const sw = box.w / 170;
  const aff = a.affectedSide;
  const pr = P[468]!;
  const pl = P[473]!;
  const f = faceFrame(P);
  const ex = f.ex;
  const ey = f.ey;
  const along = (o: Vec2, d: Vec2, k: number): Vec2 => ({ x: o.x + d.x * k, y: o.y + d.y * k });
  const lineAt = (o: Vec2, len: number) => [along(o, ex, -len), along(o, ex, len)] as const;
  const L = f.unitPx;
  const mid = { x: (pr.x + pl.x) / 2, y: (pr.y + pl.y) / 2 };
  const sideMarks = (s: Side) => {
    const c = s === aff ? COLOR.aff : COLOR.healthy;
    const pupil = s === 'right' ? pr : pl;
    const idx = SIDE[s];
    const brow = idx.brow
      .map((i) => P[i]!)
      .reduce((m, p) => ({ x: m.x + p.x / idx.brow.length, y: m.y + p.y / idx.brow.length }), { x: 0, y: 0 });
    const corner = P[idx.mouthCorner]!;
    const [b0, b1] = lineAt(brow, 0.16 * L);
    const [c0, c1] = lineAt(corner, 0.14 * L);
    return (
      <g stroke={c} fill={c}>
        <line class="halo" x1={pupil.x} y1={pupil.y} x2={brow.x} y2={brow.y} stroke-width={sw * 1.6} />
        <line class="halo" x1={b0.x} y1={b0.y} x2={b1.x} y2={b1.y} stroke-width={sw * 2.2} />
        <line class="halo" x1={c0.x} y1={c0.y} x2={c1.x} y2={c1.y} stroke-width={sw * 2.2} />
        <circle cx={corner.x} cy={corner.y} r={sw * 3} stroke="#fff" stroke-width={sw} />
        <circle cx={pupil.x} cy={pupil.y} r={sw * 2.2} stroke="#fff" stroke-width={sw * 0.8} />
      </g>
    );
  };
  const pline = [along(pr, { x: pr.x - pl.x, y: pr.y - pl.y }, 0.45), along(pl, { x: pl.x - pr.x, y: pl.y - pr.y }, 0.45)];
  const m0 = along(mid, ey, -0.9 * L);
  const m1 = along(mid, ey, 2.0 * L);
  const tag = (s: Side) => `환자 ${s === 'right' ? '오른쪽' : '왼쪽'} · ${s === aff ? '마비 쪽' : '건강한 쪽'}`;
  return (
    <svg class="photo-frame" viewBox={`${box.x} ${box.y} ${box.w} ${box.h}`} role="img" aria-label={`${record.label} 사진과 측정선`}>
      <image href={record.imageUrl} x="0" y="0" width={a.keyframe.width} height={a.keyframe.height} preserveAspectRatio="none" />
      {contours &&
        Object.values(CONTOURS).map((c) => (
          <polyline
            points={c.map((i) => `${P[i]!.x},${P[i]!.y}`).join(' ')}
            fill="none"
            stroke="rgba(255,255,255,0.75)"
            stroke-width={sw * 0.8}
          />
        ))}
      <g fill="none">
        <line class="halo" x1={pline[0]!.x} y1={pline[0]!.y} x2={pline[1]!.x} y2={pline[1]!.y} stroke="#fff" stroke-width={sw} />
        <line class="halo" x1={m0.x} y1={m0.y} x2={m1.x} y2={m1.y} stroke="#fff" stroke-width={sw * 0.8} opacity="0.8" />
      </g>
      {sideMarks('right')}
      {sideMarks('left')}
      <g font-size={box.w / 24} font-weight="700" class="photo-tag">
        <text x={box.x + box.w * 0.03} y={box.y + box.h * 0.06}>
          {tag('right')}
        </text>
        <text x={box.x + box.w * 0.97} y={box.y + box.h * 0.06} text-anchor="end">
          {tag('left')}
        </text>
      </g>
    </svg>
  );
}

/** SVG matrix mapping image pixels into face units (pupil midpoint origin, IPD = 1). */
function faceMatrix(a: StillAnalysis): string {
  const f = faceFrame(pts(a));
  const k = 1 / f.unitPx;
  const [A, B, C, D] = [f.ex.x * k, f.ey.x * k, f.ex.y * k, f.ey.y * k];
  const E = -(A * f.origin.x + C * f.origin.y);
  const F = -(B * f.origin.x + D * f.origin.y);
  return `matrix(${A} ${B} ${C} ${D} ${E} ${F})`;
}

/** Two photos aligned on the pupils (same position, scale and roll) with a split slider. */
export function AlignedCompare({ before, after }: { before: PhotoRecord; after: PhotoRecord }) {
  const [split, setSplit] = useState(50);
  const a = before.analysis;
  const b = after.analysis;
  if (!a || !b || !before.imageUrl || !after.imageUrl) return null;
  const vb = { x: -1.55, y: -1.45, w: 3.1, h: 3.7 };
  const cut = vb.x + (vb.w * split) / 100;
  return (
    <div class="stack">
      <svg class="photo-frame" viewBox={`${vb.x} ${vb.y} ${vb.w} ${vb.h}`} role="img" aria-label={`${before.label}과 ${after.label} 비교`}>
        <defs>
          <clipPath id="cmp-right">
            <rect x={cut} y={vb.y} width={vb.x + vb.w - cut} height={vb.h} />
          </clipPath>
        </defs>
        <image
          href={before.imageUrl}
          width={a.keyframe.width}
          height={a.keyframe.height}
          transform={faceMatrix(a)}
          preserveAspectRatio="none"
        />
        <g clip-path="url(#cmp-right)">
          <rect x={vb.x} y={vb.y} width={vb.w} height={vb.h} fill="#111" />
          <image
            href={after.imageUrl}
            width={b.keyframe.width}
            height={b.keyframe.height}
            transform={faceMatrix(b)}
            preserveAspectRatio="none"
          />
        </g>
        <line x1={cut} x2={cut} y1={vb.y} y2={vb.y + vb.h} stroke="#fff" stroke-width="0.015" />
        <line x1={vb.x} x2={vb.x + vb.w} y1={0} y2={0} stroke="rgba(255,255,255,0.55)" stroke-width="0.008" />
        <g font-size="0.11" font-weight="700" class="photo-tag">
          <text x={vb.x + 0.06} y={vb.y + vb.h - 0.08}>
            {before.label}
          </text>
          <text x={vb.x + vb.w - 0.06} y={vb.y + vb.h - 0.08} text-anchor="end">
            {after.label}
          </text>
        </g>
      </svg>
      <input
        type="range"
        min={0}
        max={100}
        value={split}
        aria-label="비교 위치"
        onInput={(e) => setSplit(Number((e.target as HTMLInputElement).value))}
        class="range"
      />
      <p class="xsmall muted">두 사진을 동공 위치에 맞춰 같은 크기·기울기로 정렬했습니다. 가로선은 동공선입니다.</p>
    </div>
  );
}

export function RegionRows({ a }: { a: StillAnalysis }) {
  return (
    <div class="list">
      {STILL_REGIONS.map((r) => {
        const x = a.regions[r];
        const dim = !x.relevant || x.excluded;
        return (
          <div class="list-item" style={{ cursor: 'default', opacity: dim ? 0.55 : 1 }}>
            <div style={{ width: '52px', fontWeight: 650 }}>{REGION_NAME[r]}</div>
            <div class="grow small">
              {x.excluded ? '측정 제외' : regionReading(r, x.diffMm)}
              {!x.relevant && !x.excluded && <span class="xsmall muted"> · 이 표정의 주 관찰 부위 아님</span>}
            </div>
            {!x.excluded && <span class={`chip ${dim ? '' : BAND_CHIP[x.band]}`}>{BAND_LABEL[x.band]}</span>}
          </div>
        );
      })}
    </div>
  );
}

export function Attribution({ source }: { source: CaseSource }) {
  return (
    <p class="xsmall muted">
      사진:{' '}
      <a href={source.page} target="_blank" rel="noopener noreferrer">
        {source.author} · Wikimedia Commons
      </a>{' '}
      ·{' '}
      <a href={source.licenseUrl} target="_blank" rel="noopener noreferrer">
        {source.license}
      </a>{' '}
      · {source.changes}
    </p>
  );
}

export function sourceOf(r: PhotoRecord): CaseSource | null {
  const c = r.caseId ? caseById(r.caseId) : undefined;
  return c?.photos.find((p) => p.id === r.photoId)?.source ?? null;
}

export function PhotoTimeline({
  records,
  selected,
  onSelect,
}: {
  records: PhotoRecord[];
  selected: string;
  onSelect: (id: string) => void;
}) {
  return (
    <div class="tabs-scroll" role="listbox" aria-label="사진 목록">
      {records.map((r) => (
        <button
          class={`thumb ${r.id === selected ? 'on' : ''}`}
          role="option"
          aria-selected={r.id === selected}
          onClick={() => onSelect(r.id)}
          title={r.label}
        >
          {r.imageUrl && <img src={r.imageUrl} alt="" loading="lazy" />}
          <span>{r.day !== null ? `${r.day}일째` : EXPRESSION_LABEL[r.expression]}</span>
          <small>{r.day !== null ? EXPRESSION_LABEL[r.expression] : ''}</small>
        </button>
      ))}
    </div>
  );
}

const TREND_COLOR: Record<StillRegion, string> = {
  mouth: 'var(--series-1)',
  brow: 'var(--series-2)',
  eye: 'var(--series-3)',
  midface: 'var(--series-4)',
};

const trendLabel = (r: StillRegion) => `${REGION_NAME[r]} (${TREND_TASK_LABEL[r]})`;

/** Chart series for the same-task trend (see cases/trend.ts). */
export function trendSeries(records: readonly PhotoRecord[]): Series[] {
  return trendLines(records).map((l) => ({ id: l.region, label: trendLabel(l.region), color: TREND_COLOR[l.region], points: l.points }));
}

export function StillTrend({ records, height = 200 }: { records: readonly PhotoRecord[]; height?: number }) {
  const series = trendSeries(records);
  if (!series.some((s) => s.points.length >= 2)) return null;
  const max = Math.max(5, ...series.flatMap((s) => s.points.map((p) => p.y)));
  const yMax = Math.ceil(max / 5) * 5;
  const ticks = Array.from({ length: yMax / 5 + 1 }, (_, i) => i * 5);
  const byDay = new Map<number, string[]>();
  for (const r of records) if (r.day !== null) byDay.set(r.day, [...(byDay.get(r.day) ?? []), EXPRESSION_LABEL[r.expression]]);
  return (
    <div class="stack">
      <Legend series={series} />
      <LineChart
        ariaLabel="같은 과제의 좌우 차이 추이"
        series={series}
        yMax={yMax}
        yTicks={ticks}
        ySuffix="mm"
        xLabel={(x) => `${x}일`}
        xTitle="발병 일차"
        height={height}
        extra={(x) => (byDay.has(x) ? `사진: ${[...new Set(byDay.get(x))].join(', ')}` : null)}
      />
    </div>
  );
}

/** First → last value of each trend region, with a display label. */
export function trendSummary(records: readonly PhotoRecord[]) {
  return baseSummary(records).map((t) => ({ ...t, label: trendLabel(t.region) }));
}
