/** Home: what the current phase is for, and up to two personal goals with their measured progress and exercises. */
import { FEATURES } from '../../config';
import { actions, useApp } from '../../data/store';
import type { Goal, SessionRecord } from '../../data/types';
import type { Phase, Region } from '../../rehab/exercises';
import { CHANGE_BAND, changeDir } from '../../rehab/findings';
import { PHASE_LABEL, type Plan } from '../../rehab/planner';
import { Icon } from '../icons';

export const GOAL_LABEL: Record<Goal, string> = {
  eye: '눈 잘 감기',
  smile: '웃는 모습',
  brow: '이마·눈썹',
  synk: '연합운동 줄이기',
};
export const MAX_GOALS = 2;

/** Same wording as the plan rules (planner.ts phaseOf, SRS-RHB-001/003) and the exercise cautions. */
const PHASE_FOCUS: Record<Phase, { focus: string; avoid: string }> = {
  acute: { focus: '눈 보호와 부드러운 마사지', avoid: '강한 힘이나 반복 운동은 아직 하지 않습니다.' },
  recovery: { focus: '거울을 보며 작고 대칭적인 움직임', avoid: '건강한 쪽이 과하게 움직이면 동작 크기를 줄입니다.' },
  synkinesis: { focus: '스트레칭과 분리 운동으로 함께 움직임 줄이기', avoid: '힘을 빼고 천천히, 최대 힘은 쓰지 않습니다.' },
};

const GOAL_REGION: Record<Goal, Region | null> = { eye: 'eye', smile: 'mouth', brow: 'forehead', synk: null };

type Scored = SessionRecord & { analysis: { scores: NonNullable<SessionRecord['analysis']['scores']> } };

/** One line of measured progress for a goal, or null without an assessment. */
export function goalProgress(goal: Goal, scored: readonly Scored[]): string | null {
  const first = scored[0]?.analysis.scores;
  const last = scored[scored.length - 1]?.analysis.scores;
  const prev = scored[scored.length - 2]?.analysis.scores;
  if (!first || !last) return null;
  if (goal === 'synk') {
    const d = prev ? last.synkinesisScore - prev.synkinesisScore : 0;
    return `동반운동 점수(추정, 낮을수록 좋음) ${first.synkinesisScore} → ${last.synkinesisScore}${prev ? ` · 직전 대비 ${d === 0 ? '같음' : d < 0 ? `${-d} 줄어듦` : `${d} 늘어남`}` : ''}`;
  }
  const key = goal === 'eye' ? 'eye' : goal === 'smile' ? 'mouth' : 'forehead';
  const dir = prev ? changeDir(last.regional[key] - prev.regional[key], CHANGE_BAND.region) : null;
  const tail = dir === null ? '' : ` · 직전 대비 ${dir === 'same' ? '변화 없음' : dir === 'up' ? '좋아짐' : '줄어듦'}`;
  const eye = goal === 'eye' ? ` · ${last.eyeClosureComplete ? '완전히 감김' : '덜 감김'}` : '';
  return `마비 쪽 움직임 ${first.regional[key]}% → ${last.regional[key]}%${eye}${tail}`;
}

export function PhaseGoals({ plan }: { plan: Plan }) {
  const { profile, sessions } = useApp();
  if (!profile) return null;
  const goals = profile.goals ?? [];
  const scored = sessions.filter((s): s is Scored => !!s.analysis.scores);
  const toggle = (g: Goal) => {
    const next = goals.includes(g) ? goals.filter((x) => x !== g) : [...goals, g].slice(-MAX_GOALS);
    void actions.saveProfile({ ...profile, goals: next });
  };
  const p = PHASE_FOCUS[plan.phase];
  return (
    <div class="card">
      <div class="card-head">
        <h3>지금 단계 · 내 목표</h3>
        <span class="chip">{PHASE_LABEL[plan.phase]}</span>
      </div>
      <p class="small" style={{ margin: '0 0 6px' }}>
        <b>{p.focus}</b>에 집중하는 시기입니다. {p.avoid}
      </p>
      <div class="xsmall ink2">목표를 {MAX_GOALS}개까지 고르면 경과와 관련 운동을 여기서 보여 드립니다.</div>
      <div class="row wrap" style={{ gap: '6px', margin: '6px 0' }} role="group" aria-label="내 목표">
        {(Object.keys(GOAL_LABEL) as Goal[]).map((g) => (
          <button class={`btn sm ${goals.includes(g) ? 'primary' : ''}`} aria-pressed={goals.includes(g)} onClick={() => toggle(g)}>
            {GOAL_LABEL[g]}
          </button>
        ))}
      </div>
      {goals.map((g) => {
        const region = GOAL_REGION[g];
        const items =
          FEATURES.rehab === 'off'
            ? []
            : region
              ? plan.items.filter((i) => i.exercise.regions.includes(region))
              : [
                  ...plan.items.filter((i) => i.exercise.kind === 'dissociation'),
                  ...plan.items.filter((i) => i.exercise.kind === 'stretch'),
                ];
        const progress = goalProgress(g, scored);
        return (
          <div class="finding" style={{ marginTop: '6px' }}>
            <b class="small">{GOAL_LABEL[g]}</b>
            <div class="xsmall ink2">{progress ?? '평가를 하면 경과가 여기에 나옵니다.'}</div>
            {items.length > 0 ? (
              <div class="row wrap" style={{ gap: '6px', marginTop: '4px' }}>
                {items.slice(0, 3).map((i) => (
                  <a class="btn sm" href={`#/exercise/${i.exercise.id}`}>
                    {i.exercise.title} <Icon name="chev" />
                  </a>
                ))}
              </div>
            ) : (
              FEATURES.rehab !== 'off' && <div class="xsmall muted">오늘 계획에는 관련 운동이 없습니다(시기·측정에 맞춰 배정됩니다).</div>
            )}
          </div>
        );
      })}
    </div>
  );
}
